    serde_json::from_str(r#"[{"name":"keeper.journey.append","description":"Append a closed card's reflection (from keeper.card.consolidate's lesson memory) to project_journey table. Pure deterministic — no AI. Idempotent. Fires card_phase_events phase=journey_appended which is the final phase signal for the post-QA pipeline.","owner_agent":"keeper","steps_json":"[{\"skill\":\"keeper-journey-append\",\"input\":\"$.input\",\"as\":\"journey\"}]","returns":"$.results.journey","on_failure":"abort"},{"name":"keeper.card.consolidate","description":"Distill a finished card's journey into a single 'lesson' memory + numeric metrics. Reads the MAN review evidence; calls mid+warm AI for a 4-6 sentence reflection + concrete lessons. INSERTs memory.memories type=lesson + fires card_phase_events phase=keeper_consolidated.","owner_agent":"keeper","steps_json":"[{\"skill\":\"keeper-card-consolidate\",\"input\":\"$.input\",\"as\":\"reflection\"}]","returns":"$.results.reflection","on_failure":"abort"},{"name":"keeper.memory.consolidate","description":"Distill raw memories into a narrative (tier-2). Links narrative ← constituents via memory_links kind=derived_from.","owner_agent":"keeper","steps_json":"[{\"skill\":\"memory-consolidate\",\"input\":\"$.input\",\"as\":\"narrative\"}]","returns":"$.results.narrative","on_failure":"abort"},{"name":"keeper.memory.add","description":"Append a new memory (lesson/preference/decision/reference/correction). Audited via with-audit; no git commit per memory.","owner_agent":"keeper","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"memory-add\",\"wrappedInput\":\"$.input\",\"operation\":\"memory.add\",\"entity_type\":\"memory\",\"entity_id\":\"$.input.title\"},\"as\":\"memory\"}]","returns":"$.results.memory","on_failure":"rollback"},{"name":"keeper.memory.supersede","description":"Mark an old memory as superseded by a new one (functional \"delete\"; row stays).","owner_agent":"keeper","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"memory-supersede\",\"wrappedInput\":\"$.input\",\"operation\":\"memory.supersede\",\"entity_type\":\"memory\",\"entity_id\":\"$.input.old_id\"},\"as\":\"memory\"}]","returns":"$.results.memory","on_failure":"rollback"},{"name":"keeper.memory.validate","description":"Flip a memory to validated=1 (and confidence=1.0 by default). Validated memories are eligible for fine-tune export.","owner_agent":"keeper","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"memory-validate\",\"wrappedInput\":\"$.input\",\"operation\":\"memory.validate\",\"entity_type\":\"memory\",\"entity_id\":\"$.input.id\"},\"as\":\"memory\"}]","returns":"$.results.memory","on_failure":"rollback"},{"name":"keeper.memory.embed.store","description":"Store a pre-computed embedding vector for a memory. Decoupled from any specific embedding model — caller supplies the vector.","owner_agent":"keeper","steps_json":"[{\"skill\":\"memory-embed-store\",\"input\":\"$.input\",\"as\":\"embedding\"}]","returns":"$.results.embedding","on_failure":"abort"},{"name":"keeper.memory.link.add","description":"Add a typed directed edge between two memories. Kinds: contradicts | extends | derived_from | related | corrects. UNIQUE on (from,to,kind).","owner_agent":"keeper","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"memory-link-add\",\"wrappedInput\":\"$.input\",\"operation\":\"memory.link.add\",\"entity_type\":\"memory\",\"entity_id\":\"$.input.from_memory_id\"},\"as\":\"link\"}]","returns":"$.results.link","on_failure":"rollback"},{"name":"keeper.memory.use.record","description":"Record that a memory was retrieved/used in some context. Self-learning feedback loop (half 1 — capturing the use).","owner_agent":"keeper","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"memory-use-record\",\"wrappedInput\":\"$.input\",\"operation\":\"memory.use.record\",\"entity_type\":\"memory\",\"entity_id\":\"$.input.memory_id\"},\"as\":\"use\"}]","returns":"$.results.use","on_failure":"rollback"},{"name":"keeper.memory.use.rate","description":"Record an outcome rating (helpful | irrelevant | misleading | partial) for a memory use. Self-learning feedback loop (half 2 — closing it).","owner_agent":"keeper","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"memory-use-rate\",\"wrappedInput\":\"$.input\",\"operation\":\"memory.use.rate\",\"entity_type\":\"memory\",\"entity_id\":\"$.input.use_id\"},\"as\":\"outcome\"}]","returns":"$.results.outcome","on_failure":"rollback"},{"name":"keeper.memory.capture-correction","description":"Capture a (mistake → fix → guidance) memory of type=correction after a qa_fail → qa_pass cycle.","owner_agent":"keeper","steps_json":"[{\"skill\":\"keeper-memory-capture-correction\",\"input\":\"$.input\",\"as\":\"memory\"}]","returns":"$.results.memory","on_failure":"abort"},{"name":"keeper.memory.embed.compute","description":"Compute an embedding vector for a text via local transformers.js (Xenova/bge-base-en-v1.5, 768-dim). Returns {model, dims, vector}. No DB writes.","owner_agent":"keeper","steps_json":"[{\"skill\":\"embed\",\"input\":\"$.input\",\"as\":\"embedding\"}]","returns":"$.results.embedding","on_failure":"abort"},{"name":"keeper.memory.embed.full","description":"Compute embedding for a memory text AND store it (one atomic call). Input: {memory_id, text, model?, embedded_field?}.","owner_agent":"keeper","steps_json":"[{\"skill\":\"embed\",\"input\":{\"text\":\"$.input.text\",\"model\":\"$.input.model\"},\"as\":\"embedding\"},{\"skill\":\"memory-embed-store\",\"input\":{\"memory_id\":\"$.input.memory_id\",\"model\":\"$.results.embedding.model\",\"vector\":\"$.results.embedding.vector\",\"embedded_field\":\"$.input.embedded_field\"},\"as\":\"stored\"}]","returns":"$.results.stored","on_failure":"abort"},{"name":"keeper.review","description":"Keeper periodic scan: surface tier-1 memories not yet validated/linked + consolidation candidates. Read-only — produces a plan, does not auto-execute.","owner_agent":"keeper","steps_json":"[{\"skill\":\"keeper-review\",\"input\":\"$.input\",\"as\":\"report\"}]","returns":"$.results.report","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
